import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十卦 鼎 火風鼎 離上巽下","description":"周易 - 第五十卦 鼎 火風鼎 離上巽下","frontmatter":{"title":"第五十卦 鼎 火風鼎 離上巽下","description":"周易 - 第五十卦 鼎 火風鼎 離上巽下"},"headers":[],"relativePath":"classics/zhouyi/051.md","filePath":"classics/zhouyi/051.md"}'),l={name:"classics/zhouyi/051.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="鼎" tabindex="-1">鼎 <a class="header-anchor" href="#鼎" aria-label="Permalink to “鼎”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元吉，亨。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>木上有火，鼎；君子以正位凝命。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>鼎顛趾，利出否，得妾以其子，無咎。 象曰：鼎顛趾，未悖也。利出否，以從貴也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>鼎有實，我仇有疾，不我能即，吉。象曰：鼎有實，慎所之也。我仇有疾，終無尤也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。象曰：鼎耳革，失其義也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>鼎折足，覆公□，其形渥，兇。象曰：覆公束，信如何也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>鼎黃耳金鉉，利貞。象曰：鼎黃耳，中以為實也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>鼎玉鉉，大吉，無不利。象曰：玉鉉在上，剛柔節也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
